				vof += nvof;			/* Move to next vertex */
				nvof = (wo1 & 0x1ffffff);	/* Extract offset value */
				wo1 = (wo1 >> 25);		/* Extract weighting value */
				vwe = wo0 - wo1;		/* Baricentric weighting */
