					XFR(wot, wo2);
					CJ(wo1, wot, shs2);
					XFR(wo2, wo1);
					CXJ(wo0, wot, wo1, shs2);
					XFR(wo1, wo0);
					XFR(wo0, wot);
shs2:;
					XFR(wot, wo3);
					CJ(wo2, wot, shs3);
					XFR(wo3, wo2);
					CXJ(wo1, wot, wo2, shs3);
					XFR(wo2, wo1);
					CXJ(wo0, wot, wo1, shs3);
					XFR(wo1, wo0);
					XFR(wo0, wot);
shs3:;
					XFR(wot, wo4);
					CJ(wo3, wot, shs4);
					XFR(wo4, wo3);
					CXJ(wo2, wot, wo3, shs4);
					XFR(wo3, wo2);
					CXJ(wo1, wot, wo2, shs4);
					XFR(wo2, wo1);
					CXJ(wo0, wot, wo1, shs4);
					XFR(wo1, wo0);
					XFR(wo0, wot);
shs4:;
					XFR(wot, wo5);
					CJ(wo4, wot, shs5);
					XFR(wo5, wo4);
					CXJ(wo3, wot, wo4, shs5);
					XFR(wo4, wo3);
					CXJ(wo2, wot, wo3, shs5);
					XFR(wo3, wo2);
					CXJ(wo1, wot, wo2, shs5);
					XFR(wo2, wo1);
					CXJ(wo0, wot, wo1, shs5);
					XFR(wo1, wo0);
					XFR(wo0, wot);
