					CXJ(wo3, wot, wo4, shs6);
					XFR(wo4, wo3);
					CXJ(wo2, wot, wo3, shs6);
					XFR(wo3, wo2);
					CXJ(wo1, wot, wo2, shs6);
					XFR(wo2, wo1);
					CXJ(wo0, wot, wo1, shs6);
